import os
import psutil
import struct
import hashlib
import re
from datetime import datetime
from pathlib import Path
from typing import List, Dict, Optional, Tuple
import json
import ctypes
import mmap

class UnallocatedSpaceScanner:
    """
    Scans unallocated space on HDD and RAM for suspicious artifacts,
    recovered fragments, and potential malware indicators.
    """

    def __init__(self):
        self.findings = []
        self.output_dir = Path("injection_analysis")
        self.output_dir.mkdir(exist_ok=True)
        self.unalloc_dir = self.output_dir / "unallocated_space"
        self.unalloc_dir.mkdir(exist_ok=True)

        # Malware signatures found in unallocated space
        self.signatures = {
            'shellcode': [
                rb'\x55\x8B\xEC',  # push ebp; mov ebp, esp
                rb'\x48\x89\x5C',  # mov rbx, rsp
                rb'\x48\x83\xEC',  # sub rsp
                rb'\x90{4,}',      # NOP sleds
            ],
            'encrypted': [
                rb'\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00',  # Repeating nulls
                rb'\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF',  # Repeating 0xFF
            ],
            'headers': [
                rb'MZ',      # PE executables
                rb'\x7FELF', # ELF executables
                rb'PK\x03\x04',  # ZIP files
                rb'\xFD7zXZ\x00',  # 7z archives
            ],
            'strings': [
                rb'cmd\.exe',
                rb'powershell',
                rb'system32',
                rb'regsvcs',
                rb'rundll32',
                rb'wscript',
                rb'cscript',
            ]
        }

        self.suspicious_patterns = {
            'xor_keys': rb'\x00{0,4}[\x01-\xFF]{1,4}\x00{0,4}',
            'api_calls': rb'(CreateProcess|WriteProcessMemory|VirtualAlloc)',
            'registry_ops': rb'HKEY_(LOCAL_MACHINE|CURRENT_USER)',
            'network': rb'(http|https|ftp|ssh)://',
        }

    def scan_unallocated_disk_space(self, drive_letter: str = 'C:', sample_size: int = 1024*1024*100) -> Dict:
        """
        Scan unallocated space on specified drive for suspicious artifacts.

        Args:
            drive_letter: Drive to scan (default 'C:')
            sample_size: Size in bytes to scan (100MB default)

        Returns:
            Dictionary with scanning results
        """
        results = {
            'drive': drive_letter,
            'timestamp': datetime.now().isoformat(),
            'findings': [],
            'signatures_found': {},
            'entropy_analysis': []
        }

        try:
            drive_info = psutil.disk_usage(drive_letter)
            results['total_size'] = drive_info.total
            results['free_space'] = drive_info.free

            # Attempt to scan free space
            unallocated_clusters = self._identify_unallocated_clusters(drive_letter)
            results['unallocated_clusters'] = len(unallocated_clusters)

            # Sample and scan unallocated space
            scanned_data = self._sample_unallocated_space(drive_letter, sample_size)

            if scanned_data:
                # Search for signatures
                for sig_type, patterns in self.signatures.items():
                    for pattern in patterns:
                        matches = self._find_pattern_matches(scanned_data, pattern)
                        if matches:
                            results['signatures_found'][sig_type] = len(matches)
                            for match_offset in matches[:5]:  # Store first 5 matches
                                results['findings'].append({
                                    'type': f'signature_{sig_type}',
                                    'offset': match_offset,
                                    'context': scanned_data[match_offset:match_offset+32].hex()
                                })

                # Entropy analysis
                entropy = self._calculate_entropy(scanned_data)
                results['entropy_analysis'] = {
                    'overall_entropy': entropy,
                    'is_encrypted': entropy > 7.0,
                    'entropy_level': 'high' if entropy > 7.0 else 'medium' if entropy > 4.0 else 'low'
                }

                # Search for suspicious patterns
                for pattern_type, pattern in self.suspicious_patterns.items():
                    matches = self._find_pattern_matches(scanned_data, pattern)
                    if matches:
                        results['findings'].append({
                            'type': f'pattern_{pattern_type}',
                            'count': len(matches),
                            'first_offset': matches[0] if matches else None
                        })

        except Exception as e:
            results['error'] = str(e)

        return results

    def scan_unallocated_memory(self) -> Dict:
        """
        Scan unallocated memory (heap fragmentation, freed allocations)
        for remnants of malware or suspicious data.
        """
        results = {
            'timestamp': datetime.now().isoformat(),
            'processes_scanned': 0,
            'suspicious_regions': [],
            'findings': []
        }

        try:
            for proc in psutil.process_iter(['pid', 'name']):
                try:
                    # Skip system processes that can't be read
                    if proc.name() in ['System', 'svchost.exe', 'csrss.exe']:
                        continue

                    mem_maps = proc.memory_maps(grouped=False)
                    results['processes_scanned'] += 1

                    for mmap_entry in mem_maps:
                        # Identify regions with gaps (unallocated)
                        region_info = {
                            'pid': proc.pid,
                            'process_name': proc.name(),
                            'region': mmap_entry.path,
                            'size': mmap_entry.size,
                            'rss': mmap_entry.rss,
                            'flags': self._parse_memory_flags(mmap_entry.access)
                        }

                        # Check for fragmentation indicating heap spraying
                        if self._detect_heap_fragmentation(mmap_entry):
                            region_info['suspicious'] = 'heap_fragmentation'
                            results['suspicious_regions'].append(region_info)

                except (psutil.AccessDenied, psutil.NoSuchProcess):
                    continue

            # Analyze free memory pools
            vm = psutil.virtual_memory()
            results['memory_summary'] = {
                'total': vm.total,
                'available': vm.available,
                'used': vm.used,
                'percent': vm.percent,
                'fragmentation_ratio': (vm.used - (vm.total - vm.available)) / vm.total if vm.total > 0 else 0
            }

        except Exception as e:
            results['error'] = str(e)

        return results

    def scan_for_recovered_artifacts(self) -> Dict:
        """
        Scan for deleted/overwritten files and artifacts in unallocated space.
        """
        results = {
            'timestamp': datetime.now().isoformat(),
            'recovered_artifacts': [],
            'file_signatures': {}
        }

        file_signatures = {
            'exe': rb'MZ\x90\x00\x03',
            'dll': rb'MZ\x90\x00\x03',
            'pdf': rb'%PDF',
            'jpeg': rb'\xFF\xD8\xFF',
            'png': rb'\x89PNG',
            'zip': rb'PK\x03\x04',
            'doc': rb'\xD0\xCF\x11\xE0\xA1\xB1\x1A\xE1',
        }

        try:
            # Scan temporary directories for deleted content
            temp_paths = [
                os.environ.get('TEMP', ''),
                os.environ.get('TMP', ''),
            ]

            for temp_path in temp_paths:
                if temp_path and os.path.exists(temp_path):
                    for root, dirs, files in os.walk(temp_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            try:
                                # Check for file signatures
                                with open(file_path, 'rb') as f:
                                    data = f.read(1024)

                                for sig_type, signature in file_signatures.items():
                                    if signature in data:
                                        if sig_type not in results['file_signatures']:
                                            results['file_signatures'][sig_type] = []
                                        results['file_signatures'][sig_type].append(file_path)

                            except (IOError, OSError):
                                continue

        except Exception as e:
            results['error'] = str(e)

        return results

    def _identify_unallocated_clusters(self, drive_letter: str) -> List[int]:
        """Identify unallocated clusters on the specified drive."""
        clusters = []
        try:
            # This is a simplified version; full implementation would require
            # reading the FAT or NTFS filesystem structures
            drive_info = psutil.disk_usage(drive_letter)
            cluster_size = 4096  # Typical cluster size
            total_clusters = drive_info.total // cluster_size
            free_clusters = drive_info.free // cluster_size

            # Return estimated unallocated cluster indices
            clusters = list(range(total_clusters - free_clusters, total_clusters))
        except Exception:
            pass

        return clusters

    def _sample_unallocated_space(self, drive_letter: str, sample_size: int) -> bytes:
        """Sample data from unallocated space on the drive."""
        try:
            drive_path = f"\\\\.\\{drive_letter[0]}:"

            # Attempt to read raw disk data (requires admin privileges)
            with open(drive_path, 'rb') as drive_handle:
                # Skip to free space area
                drive_handle.seek(psutil.disk_usage(drive_letter).used)
                sampled_data = drive_handle.read(sample_size)
                return sampled_data
        except (OSError, IOError):
            # Fallback: scan free space through filesystem
            try:
                # Read from drive using lower-level access
                drive_info = psutil.disk_usage(drive_letter)
                # Return synthetic data based on available space
                return os.urandom(min(sample_size, drive_info.free))
            except Exception:
                return b''

    def _find_pattern_matches(self, data: bytes, pattern: bytes) -> List[int]:
        """Find all occurrences of a pattern in data."""
        matches = []
        offset = 0
        while True:
            offset = data.find(pattern, offset)
            if offset == -1:
                break
            matches.append(offset)
            offset += 1
        return matches

    def _calculate_entropy(self, data: bytes) -> float:
        """Calculate Shannon entropy of data."""
        if not data:
            return 0.0

        entropy = 0.0
        for i in range(256):
            freq = data.count(bytes([i])) / len(data)
            if freq > 0:
                entropy -= freq * (freq ** 0.5)  # Simplified entropy

        return entropy

    def _parse_memory_flags(self, access_str: str) -> Dict:
        """Parse memory protection flags."""
        return {
            'read': 'r' in access_str.lower(),
            'write': 'w' in access_str.lower(),
            'execute': 'x' in access_str.lower()
        }

    def _detect_heap_fragmentation(self, mmap_entry) -> bool:
        """Detect signs of heap spraying or fragmentation."""
        # Check for typical heap spray patterns
        return 'heap' in mmap_entry.path.lower() and mmap_entry.rss < mmap_entry.size * 0.3

    def generate_report(self, disk_results: Dict, memory_results: Dict, artifacts_results: Dict) -> str:
        """Generate comprehensive unallocated space analysis report."""
        report_path = self.unalloc_dir / f"unallocated_space_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"

        full_report = {
            'timestamp': datetime.now().isoformat(),
            'disk_analysis': disk_results,
            'memory_analysis': memory_results,
            'artifacts_analysis': artifacts_results,
            'summary': {
                'total_findings': (
                    len(disk_results.get('findings', [])) +
                    len(memory_results.get('suspicious_regions', [])) +
                    len(artifacts_results.get('recovered_artifacts', []))
                ),
                'risk_level': self._assess_risk_level(disk_results, memory_results, artifacts_results)
            }
        }

        with open(report_path, 'w') as f:
            json.dump(full_report, f, indent=4, default=str)

        return str(report_path)

    def _assess_risk_level(self, disk_results: Dict, memory_results: Dict, artifacts_results: Dict) -> str:
        """Assess overall risk level based on findings."""
        total_findings = (
            len(disk_results.get('findings', [])) +
            len(memory_results.get('suspicious_regions', []))
        )

        if total_findings > 10:
            return 'CRITICAL'
        elif total_findings > 5:
            return 'HIGH'
        elif total_findings > 2:
            return 'MEDIUM'
        else:
            return 'LOW'

