import os
import psutil
import hashlib
import struct
import json
from datetime import datetime
from pathlib import Path
from typing import List, Dict, Optional, Tuple
import ctypes
import re

class HDDFreeSpaceScanner:
    """
    Dedicated HDD free space scanner for detecting:
    - Deleted executable files
    - Malware fragments
    - Hidden data in slack space
    - Unallocated clusters with suspicious content
    """

    def __init__(self):
        self.output_dir = Path("injection_analysis")
        self.output_dir.mkdir(exist_ok=True)
        self.hdd_scan_dir = self.output_dir / "hdd_scans"
        self.hdd_scan_dir.mkdir(exist_ok=True)

        # File signatures for recovery
        self.file_signatures = {
            'executable': {
                'PE32': (0, b'MZ\x90\x00\x03'),
                'PE64': (0, b'MZ\x90\x00\x02'),
                'ELF': (0, b'\x7FELF'),
                'Mach-O': (0, b'\xFE\xED\xFA'),
            },
            'archive': {
                'ZIP': (0, b'PK\x03\x04'),
                '7z': (0, b'7z\xBC\xAF\x27\x1C'),
                'RAR': (0, b'Rar!\x1A\x07'),
                'GZIP': (0, b'\x1F\x8B'),
                'TAR': (257, b'ustar'),
            },
