            slack_start = ((file_size + self.cluster_size - 1) // self.cluster_size) * self.cluster_size
            slack_size = slack_start - file_size

            if slack_size > 0:
                with open(file_path, 'rb') as f:
                    f.seek(file_size)
                    return f.read(slack_size)
        except (OSError, IOError):
            pass

        return b''

    def _calculate_entropy(self, data: bytes) -> float:
        """Calculate Shannon entropy."""
        if not data:
            return 0.0

        entropy = 0.0
        for i in range(256):
            freq = data.count(bytes([i])) / len(data)
            if freq > 0:
                import math
                entropy -= freq * math.log2(freq)

        return entropy

    def _contains_suspicious_patterns(self, data: bytes) -> bool:
        """Check if data contains any suspicious patterns."""
        for patterns in self.malware_signatures.values():
            for pattern in patterns:
                if pattern in data:
                    return True
        return False

    def _find_patterns_in_data(self, data: bytes) -> List[str]:
        """Find specific patterns in data."""
        patterns = []

        for pattern_type, pattern_list in self.malware_signatures.items():
            for pattern in pattern_list:
                if pattern in data:
                    patterns.append(pattern_type)

        return patterns

    def _enumerate_mft_entries(self, drive: str) -> List[Dict]:
        """Enumerate MFT (Master File Table) entries."""
        entries = []
        try:
            for root, dirs, files in os.walk(drive + '\\'):
                for file in files:
                    file_path = os.path.join(root, file)
                    try:
                        stat = os.stat(file_path)
                        entries.append({
                            'name': file_path,
                            'size': stat.st_size,
                            'modified_time': stat.st_mtime,
                            'created_time': stat.st_ctime,
                            'deleted': False
                        })
                    except (OSError, IOError):
                        continue
        except Exception:
            pass

        return entries

    def _detect_timestamp_anomaly(self, entry: Dict) -> bool:
        """Detect timestamp anomalies that indicate suspicious activity."""
        if entry.get('deleted'):
            return True

        # Check for future timestamps
        import time
        current_time = time.time()
        if entry.get('modified_time', 0) > current_time:
            entry['timestamp_anomaly'] = 'future_timestamp'
            return True

        return False

    def _has_admin_privileges(self) -> bool:
        """Check if running with admin privileges."""
        try:
            return ctypes.windll.shell32.IsUserAnAdmin()
        except:
            return False

    def _contains_signature(self, data: bytes, signatures: Dict) -> bool:
        """Check if data contains any of the given signatures."""
        for sig_name, (pos, signature) in signatures.items():
            if signature in data:
                return True
        return False

    def generate_hdd_report(self, free_space_results: Dict, slack_results: Dict, 
                           ntfs_results: Dict, cluster_results: Dict) -> str:
        """Generate comprehensive HDD scanning report."""
        report_path = self.hdd_scan_dir / f"hdd_scan_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"

        full_report = {
            'timestamp': datetime.now().isoformat(),
            'free_space_analysis': free_space_results,
            'slack_space_analysis': slack_results,
            'ntfs_metadata_analysis': ntfs_results,
            'cluster_analysis': cluster_results,
            'summary': {
                'total_recovered_files': len(free_space_results.get('recovered_files', [])),
                'total_malware_indicators': len(free_space_results.get('malware_indicators', [])),
                'risk_assessment': self._assess_hdd_risk(free_space_results, slack_results)
            }
        }

        with open(report_path, 'w') as f:
            json.dump(full_report, f, indent=4, default=str)

        return str(report_path)

    def _assess_hdd_risk(self, free_space_results: Dict, slack_results: Dict) -> str:
        """Assess HDD-level risk based on findings."""
        risk_score = 0

        risk_score += len(free_space_results.get('malware_indicators', [])) * 5
        risk_score += len(free_space_results.get('recovered_files', [])) * 2
        risk_score += len(slack_results.get('hidden_data_found', [])) * 3

        if risk_score > 20:
            return 'CRITICAL'
        elif risk_score > 10:
            return 'HIGH'
        elif risk_score > 5:
            return 'MEDIUM'
        else:
            return 'LOW'

