"""
Integration module for Unallocated Space and HDD Free Space Scanners
Provides unified interface and GUI integration for Meliodas Counter
"""

import threading
import logging
from pathlib import Path
from datetime import datetime
from typing import Dict, Optional
import json

try:
    from UnallocatedSpaceScanner import UnallocatedSpaceScanner
except ImportError:
    UnallocatedSpaceScanner = None

try:
    from HDDFreeSpaceScanner import HDDFreeSpaceScanner
except ImportError:
    HDDFreeSpaceScanner = None


class MemoryStorageScannerManager:
    """
    Manages both unallocated memory/storage scanning operations.
    Provides unified scanning interface and report generation.
    """

    def __init__(self):
        self.unalloc_scanner = UnallocatedSpaceScanner() if UnallocatedSpaceScanner else None
        self.hdd_scanner = HDDFreeSpaceScanner() if HDDFreeSpaceScanner else None
        self.scan_in_progress = False
        self.last_results = {}

    def scan_all_storage(self, callback=None) -> Dict:
        """
        Perform comprehensive storage and memory scanning.

        Args:
            callback: Optional callback function for progress updates

        Returns:
            Dictionary with all scan results
        """
        if self.scan_in_progress:
            return {'error': 'Scan already in progress'}

        self.scan_in_progress = True
        results = {
            'timestamp': datetime.now().isoformat(),
            'scans': {}
        }

        try:
            # Scan unallocated memory
            if callback:
                callback("Scanning unallocated memory...")

            if self.unalloc_scanner:
                disk_scan = self.unalloc_scanner.scan_unallocated_disk_space('C:')
                memory_scan = self.unalloc_scanner.scan_unallocated_memory()
                artifacts_scan = self.unalloc_scanner.scan_for_recovered_artifacts()

                results['scans']['unallocated_memory'] = memory_scan
                results['scans']['recovered_artifacts'] = artifacts_scan

                unalloc_report = self.unalloc_scanner.generate_report(
                    disk_scan, memory_scan, artifacts_scan
                )
                results['scans']['unallocated_report'] = unalloc_report

            # Scan HDD free space
            if callback:
                callback("Scanning HDD free space...")

            if self.hdd_scanner:
                free_space_scan = self.hdd_scanner.scan_drive_free_space('C:')
                slack_space_scan = self.hdd_scanner.scan_slack_space('C:')
                ntfs_scan = self.hdd_scanner.scan_ntfs_metadata('C:')
                cluster_scan = self.hdd_scanner.scan_unallocated_clusters('C:')

                results['scans']['hdd_free_space'] = free_space_scan
                results['scans']['slack_space'] = slack_space_scan
                results['scans']['ntfs_metadata'] = ntfs_scan
                results['scans']['clusters'] = cluster_scan

                hdd_report = self.hdd_scanner.generate_hdd_report(
                    free_space_scan, slack_space_scan, ntfs_scan, cluster_scan
                )
                results['scans']['hdd_report'] = hdd_report

            if callback:
                callback("Storage scan complete")

            self.last_results = results
            return results

        except Exception as e:
            logging.error(f"Storage scan error: {e}")
            results['error'] = str(e)
            return results
        finally:
            self.scan_in_progress = False

    def scan_memory_only(self, callback=None) -> Dict:
        """Scan only unallocated memory."""
        if not self.unalloc_scanner:
            return {'error': 'Unallocated space scanner not available'}

        if callback:
            callback("Scanning unallocated memory...")

        try:
            results = self.unalloc_scanner.scan_unallocated_memory()
            if callback:
                callback("Memory scan complete")
            return results
        except Exception as e:
            logging.error(f"Memory scan error: {e}")
            return {'error': str(e)}

    def scan_disk_only(self, drive: str = 'C:', callback=None) -> Dict:
        """Scan only HDD free space."""
        if not self.hdd_scanner:
            return {'error': 'HDD scanner not available'}

        if callback:
            callback(f"Scanning {drive} free space...")

        try:
            results = self.hdd_scanner.scan_drive_free_space(drive)
            if callback:
                callback("Disk scan complete")
            return results
        except Exception as e:
            logging.error(f"Disk scan error: {e}")
            return {'error': str(e)}

    def get_disk_statistics(self, drive: str = 'C:') -> Dict:
        """Get disk space statistics."""
        if self.hdd_scanner:
            return self.hdd_scanner._get_drive_stats(drive)
        return {}

    def generate_combined_report(self) -> str:
        """Generate combined report from last scan."""
        if not self.last_results:
            return ''

        report_path = Path("injection_analysis/combined_storage_report.json")
        report_path.parent.mkdir(parents=True, exist_ok=True)

        with open(report_path, 'w') as f:
            json.dump(self.last_results, f, indent=4, default=str)

        return str(report_path)

    def get_findings_summary(self) -> Dict:
        """Get summary of findings from last scan."""
        if not self.last_results:
            return {
                'total_findings': 0,
                'malware_indicators': 0,
                'suspicious_regions': 0,
                'recovered_files': 0,
                'risk_level': 'UNKNOWN'
            }

        scans = self.last_results.get('scans', {})

        summary = {
            'total_findings': 0,
            'malware_indicators': 0,
            'suspicious_regions': 0,
            'recovered_files': 0,
            'risk_level': 'LOW'
        }

        # Count findings from each scan
        if 'hdd_free_space' in scans:
            hdd_results = scans['hdd_free_space']
            summary['malware_indicators'] += len(hdd_results.get('malware_indicators', []))
            summary['recovered_files'] += len(hdd_results.get('recovered_files', []))

        if 'unallocated_memory' in scans:
            mem_results = scans['unallocated_memory']
            summary['suspicious_regions'] += len(mem_results.get('suspicious_regions', []))

        summary['total_findings'] = (
            summary['malware_indicators'] +
            summary['suspicious_regions'] +
            summary['recovered_files']
        )

        # Assess risk level
        if summary['total_findings'] > 20:
            summary['risk_level'] = 'CRITICAL'
        elif summary['total_findings'] > 10:
            summary['risk_level'] = 'HIGH'
        elif summary['total_findings'] > 5:
            summary['risk_level'] = 'MEDIUM'
        else:
            summary['risk_level'] = 'LOW'

        return summary


class StorageScannerThread(threading.Thread):
    """Background thread for storage scanning."""

    def __init__(self, manager: MemoryStorageScannerManager, 
                 scan_type: str = 'all', callback=None):
        super().__init__(daemon=True)
        self.manager = manager
        self.scan_type = scan_type
        self.callback = callback
        self.results = None

    def run(self):
        """Execute scan in background thread."""
        try:
            if self.scan_type == 'all':
                self.results = self.manager.scan_all_storage(self.callback)
            elif self.scan_type == 'memory':
                self.results = self.manager.scan_memory_only(self.callback)
            elif self.scan_type == 'disk':
                self.results = self.manager.scan_disk_only(callback=self.callback)
        except Exception as e:
            logging.error(f"Scanner thread error: {e}")
            self.results = {'error': str(e)}


# GUI Integration Helper for Meliodas Counter

class StorageScannerGUIAdapter:
    """
    Adapter to integrate storage scanners into Meliodas Counter GUI
    """

    def __init__(self, gui_root):
        self.gui_root = gui_root
        self.manager = MemoryStorageScannerManager()
        self.scan_thread = None

    def add_storage_scan_tab(self, notebook):
        """Add storage scanning tab to GUI notebook."""
        import tkinter as tk
        from tkinter import ttk, messagebox, scrolledtext

        # Create frame for storage scanning
        storage_frame = ttk.Frame(notebook)
        notebook.add(storage_frame, text="Storage Scan")

        # Top panel with scan buttons
        button_frame = ttk.LabelFrame(storage_frame, text="Scan Options")
        button_frame.pack(fill='x', padx=5, pady=5)

        def start_full_scan():
            if self.scan_thread and self.scan_thread.is_alive():
                messagebox.showwarning("Already Scanning", "A scan is already in progress")
                return

            def update_progress(msg):
                progress_label.config(text=msg)
                self.gui_root.update()

            self.scan_thread = StorageScannerThread(
                self.manager, 'all', update_progress
            )
            self.scan_thread.start()

            # Wait for completion and display results
            self.gui_root.after(500, check_scan_completion, update_progress)

        def check_scan_completion(callback):
            if self.scan_thread and self.scan_thread.is_alive():
                self.gui_root.after(500, check_scan_completion, callback)
            else:
                if self.scan_thread and self.scan_thread.results:
                    display_results(self.scan_thread.results)
                    callback("Scan complete")

        def display_results(results):
            results_text.delete(1.0, tk.END)

            if 'error' in results:
                results_text.insert(tk.END, f"Error: {results['error']}")
                return

            summary = self.manager.get_findings_summary()

            output = f"Storage Scan Results\n{'='*60}\n\n"
            output += f"Timestamp: {results.get('timestamp', 'Unknown')}\n"
            output += f"Risk Level: {summary['risk_level']}\n\n"

            output += f"Findings Summary:\n"
            output += f"  Total Findings: {summary['total_findings']}\n"
            output += f"  Malware Indicators: {summary['malware_indicators']}\n"
            output += f"  Suspicious Regions: {summary['suspicious_regions']}\n"
            output += f"  Recovered Files: {summary['recovered_files']}\n\n"

            # Display detailed results
            if 'scans' in results:
                if 'hdd_free_space' in results['scans']:
                    hdd = results['scans']['hdd_free_space']
                    output += f"HDD Free Space:\n"
                    output += f"  Drive: {hdd.get('drive', 'Unknown')}\n"
                    output += f"  Total Scanned: {hdd.get('total_scanned', 0)} bytes\n"
                    output += f"  Malware Indicators: {len(hdd.get('malware_indicators', []))}\n\n"

                if 'unallocated_memory' in results['scans']:
                    mem = results['scans']['unallocated_memory']
                    output += f"Unallocated Memory:\n"
                    output += f"  Processes Scanned: {mem.get('processes_scanned', 0)}\n"
                    output += f"  Suspicious Regions: {len(mem.get('suspicious_regions', []))}\n\n"

            output += f"\nReport saved to: {self.manager.generate_combined_report()}\n"

            results_text.insert(tk.END, output)

        # Scan buttons
        ttk.Button(button_frame, text="Full Storage Scan", command=start_full_scan).pack(side='left', padx=5)

        progress_label = ttk.Label(button_frame, text="Ready")
        progress_label.pack(side='left', padx=20)

        # Results display
        results_label = ttk.LabelFrame(storage_frame, text="Scan Results")
        results_label.pack(fill='both', expand=True, padx=5, pady=5)

        results_text = scrolledtext.ScrolledText(results_label, height=20, width=80)
        results_text.pack(fill='both', expand=True)

        return storage_frame

    def open_last_report(self):
        """Open the last generated report."""
        report_path = self.manager.generate_combined_report()
        if report_path:
            import os
            try:
                os.startfile(report_path)
            except:
                messagebox.showinfo("Report Location", f"Report: {report_path}")

